static NSString *QueuePath(void){NSString *dir=[NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory,NSUserDomainMask,YES).firstObject stringByAppendingPathComponent:@"DylixAgent"];[NSFileManager.defaultManager createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];return [dir stringByAppendingPathComponent:@"build-queue.json"];}
@interface TFAIBuildQueue ()
@property NSMutableArray *jobs;
@property NSMutableDictionary *executors,*cancellations,*callbacks;
@property NSString *active,*background;
@property BOOL directRunning;
@end
@implementation TFAIBuildQueue
+ (instancetype)shared{static id shared;static dispatch_once_t once;dispatch_once(&once,^{shared=[self new];});return shared;}
- (instancetype)init{if((self=[super init])){id j=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:QueuePath()]?:NSData.data options:0 error:nil];_jobs=[NSMutableArray new];for(NSDictionary *record in [j isKindOfClass:NSArray.class]?j:@[]){if(![record isKindOfClass:NSDictionary.class]||![record[@"id"] isKindOfClass:NSString.class]||![record[@"root"] isKindOfClass:NSString.class]||![record[@"name"] isKindOfClass:NSString.class]||![record[@"state"] isKindOfClass:NSString.class])continue;NSMutableDictionary *row=[record mutableCopy];if([@[@"running",@"queued",@"cancelling"] containsObject:row[@"state"]]){row[@"state"]=@"interrupted";row[@"stage"]=DXLoc(@"上次任务已中断；重新构建将核对当前项目，不复用旧审批。");}[_jobs addObject:row];}_executors=[NSMutableDictionary new];_cancellations=[NSMutableDictionary new];_callbacks=[NSMutableDictionary new];}return self;}
- (void)persist{while(self.jobs.count>100){NSDictionary *first=self.jobs.firstObject;if([@[@"queued",@"running",@"cancelling"] containsObject:first[@"state"]])break;[self.jobs removeObjectAtIndex:0];}[[NSJSONSerialization dataWithJSONObject:self.jobs options:NSJSONWritingPrettyPrinted error:nil] writeToFile:QueuePath() options:NSDataWritingAtomic error:nil];}
- (NSArray *)tasks{@synchronized(self){NSMutableArray *copy=[NSMutableArray new];for(NSDictionary *j in self.jobs)[copy addObject:j.copy];return copy.copy;}}
- (NSString *)enqueue:(NSString *)root name:(NSString *)name executor:(TFAIBuildExecutor)executor cancel:(dispatch_block_t)cancel completion:(TFAIResult)completion{return [self enqueue:root session:nil name:name executor:executor cancel:cancel completion:completion];}
- (NSString *)enqueue:(NSString *)root session:(NSString *)sessionID name:(NSString *)name executor:(TFAIBuildExecutor)executor cancel:(dispatch_block_t)cancel completion:(TFAIResult)completion{NSAssert(NSThread.isMainThread,@"Build queue mutations run on main");if(![TFAIToolRegistry enabled:@"build_queue"]){if(self.active||self.directRunning||TMCBuildIsRunning()){if(completion)completion(nil,TFAIError(2,DXLoc(@"队列已关闭且已有构建，请等待完成后重试。")));return nil;}self.directRunning=YES;__block BOOL finished=NO;executor(^(NSString *stage,double fraction){},^(NSDictionary *result,NSError *error){dispatch_async(dispatch_get_main_queue(),^{if(finished)return;finished=YES;self.directRunning=NO;if(completion)completion(result,error);[self pump];});});return nil;}for(NSMutableDictionary *job in self.jobs)if([job[@"root"] isEqual:root]&&[(job[@"sessionID"]?:@"") isEqual:(sessionID?:@"")]&&[@[@"queued",@"running",@"cancelling"] containsObject:job[@"state"]]){if(completion)[self.callbacks[job[@"id"]] addObject:[completion copy]];return job[@"id"];}
 NSString *identifier=NSUUID.UUID.UUIDString;NSMutableDictionary *job=[@{@"id":identifier,@"root":root,@"sessionID":sessionID?:@"",@"name":name?:root.lastPathComponent,@"state":@"queued",@"stage":DXLoc(@"等待前序构建完成"),@"progress":@0,@"createdAt":@(NSDate.date.timeIntervalSince1970)} mutableCopy];[self.jobs addObject:job];self.executors[identifier]=[executor copy];if(cancel)self.cancellations[identifier]=[cancel copy];self.callbacks[identifier]=completion?[NSMutableArray arrayWithObject:[completion copy]]:[NSMutableArray new];[self persist];dispatch_async(dispatch_get_main_queue(),^{[self pump];});return identifier;
}
- (void)pump{if(self.active||self.directRunning)return;if(TMCBuildIsRunning()){__weak typeof(self) weak=self;dispatch_after(dispatch_time(DISPATCH_TIME_NOW,NSEC_PER_SEC),dispatch_get_main_queue(),^{[weak pump];});return;}NSMutableDictionary *selected=nil;for(NSMutableDictionary *j in self.jobs)if([j[@"state"] isEqual:@"queued"]){selected=j;break;}if(!selected)return;NSString *identifier=selected[@"id"];TFAIBuildExecutor execute=self.executors[identifier];if(!execute){selected[@"state"]=@"interrupted";[self persist];[self pump];return;}self.active=identifier;selected[@"state"]=@"running";selected[@"startedAt"]=@(NSDate.date.timeIntervalSince1970);selected[@"stage"]=DXLoc(@"准备项目快照");[self persist];TFAINotificationsRequest();__weak typeof(self) weak=self;self.background=TFAIBackgroundBegin(^(NSString *reason){[weak cancel:identifier];});TFAILiveUpdate(DXLoc(@"准备本机构建"),0,1);
 __block BOOL finished=NO;execute(^(NSString *stage,double fraction){dispatch_async(dispatch_get_main_queue(),^{if(finished||![weak.active isEqual:identifier])return;selected[@"stage"]=stage?:DXLoc(@"正在构建");selected[@"progress"]=@(MAX(0,MIN(1,fraction)));TFAILiveUpdate(stage?:DXLoc(@"正在本机构建"),(NSUInteger)(fraction*100),100);TFAIBackgroundUpdate(weak.background,@{@"type":@"tool_progress",@"text":stage?:DXLoc(@"本机构建")});[weak persist];});},^(NSDictionary *result,NSError *error){dispatch_async(dispatch_get_main_queue(),^{if(finished)return;finished=YES;BOOL cancelled=[selected[@"state"] isEqual:@"cancelling"];BOOL success=!cancelled&&!error&&[result[@"success"] boolValue];selected[@"state"]=cancelled?@"cancelled":success?@"completed":@"failed";selected[@"stage"]=cancelled?@"已在编译步骤边界停止":success?@"构建完成，运行待验证":error.localizedDescription?:DXLoc(@"构建失败，请查看日志与检查点");selected[@"progress"]=success?@1:selected[@"progress"];selected[@"finishedAt"]=@(NSDate.date.timeIntervalSince1970);if(result)selected[@"result"]=result;[weak persist];TFAILiveEnd(success);TFAIBackgroundEnd(weak.background,success);weak.background=nil;TFAINotifyBuildCompletion(identifier,selected[@"name"],success);NSArray *callbacks=[weak.callbacks[identifier] copy];[weak.callbacks removeObjectForKey:identifier];[weak.cancellations removeObjectForKey:identifier];[weak.executors removeObjectForKey:identifier];weak.active=nil;for(TFAIResult cb in callbacks)cb(result,cancelled?TFAIError(NSURLErrorCancelled,DXLoc(@"构建已取消；已完成的日志与检查点保留。")):error);[weak pump];});});
}
- (void)cancel:(NSString *)identifier{if(!NSThread.isMainThread){dispatch_async(dispatch_get_main_queue(),^{[self cancel:identifier];});return;}for(NSMutableDictionary *j in self.jobs)if([j[@"id"] isEqual:identifier]){if([j[@"state"] isEqual:@"queued"]){j[@"state"]=@"cancelled";j[@"stage"]=DXLoc(@"已取消排队");[self.executors removeObjectForKey:identifier];[self.cancellations removeObjectForKey:identifier];NSArray *callbacks=[self.callbacks[identifier] copy];[self.callbacks removeObjectForKey:identifier];for(TFAIResult cb in callbacks)cb(nil,TFAIError(NSURLErrorCancelled,DXLoc(@"已取消排队构建。")));}else if([j[@"state"] isEqual:@"running"]){j[@"state"]=@"cancelling";j[@"stage"]=DXLoc(@"等待当前编译步骤结束后取消");dispatch_block_t cancel=self.cancellations[identifier];if(cancel)cancel();}[self persist];return;}}

@end
@interface TFAIBuildTasks : UITableViewController
@property NSTimer *timer;
@property NSArray *rows;
@end
@implementation TFAIBuildTasks
- (void)viewDidLoad{[super viewDidLoad];self.title=DXLoc(@"构建任务队列");self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=82;}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];[self reload];__weak typeof(self) weak=self;self.timer=[NSTimer scheduledTimerWithTimeInterval:1 repeats:YES block:^(NSTimer *t){[weak reload];}];}
- (void)viewDidDisappear:(BOOL)animated{[super viewDidDisappear:animated];[self.timer invalidate];self.timer=nil;}
- (void)reload{self.rows=[TFAIBuildQueue.shared.tasks reverseObjectEnumerator].allObjects;[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return self.rows.count;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return DXLoc(@"同一时间运行一个本机构建。取消在快照或编译步骤边界生效。失败与中断保留日志、产物路径和检查点；重新构建核对当前文件并沿用现有审批。后台运行仍受iOS系统调度。");}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *j=self.rows[i.row];return AICell(j[@"name"],[NSString stringWithFormat:@"%@ · %.0f%%\n%@",j[@"state"],[j[@"progress"] doubleValue]*100,j[@"stage"]],@"hammer");}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{NSDictionary *j=self.rows[i.row];UIAlertController *a=[UIAlertController alertControllerWithTitle:j[@"name"] message:j[@"stage"] preferredStyle:UIAlertControllerStyleActionSheet];if([@[@"running",@"queued"] containsObject:j[@"state"]])[a addAction:[UIAlertAction actionWithTitle:DXLoc(@"取消任务") style:UIAlertActionStyleDestructive handler:^(UIAlertAction *x){[TFAIBuildQueue.shared cancel:j[@"id"]];[self reload];}]];if([@[@"failed",@"interrupted",@"cancelled"] containsObject:j[@"state"]])[a addAction:[UIAlertAction actionWithTitle:DXLoc(@"从检查点重新构建…") style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIAlertController *confirm=[UIAlertController alertControllerWithTitle:DXLoc(@"重新构建当前项目？") message:DXLoc(@"这是一次新的本机构建。将重新核对当前源码、配置与SDK；只有校验一致的成功编译步骤可复用，失败步骤重跑。") preferredStyle:UIAlertControllerStyleAlert];[confirm addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[confirm addAction:[UIAlertAction actionWithTitle:DXLoc(@"确认构建") style:UIAlertActionStyleDefault handler:^(UIAlertAction *y){if(!TMCStudioResumeBuild(j[@"root"],self.navigationController))AIAlert(self,DXLoc(@"项目已移动或删除"),DXLoc(@"请从项目列表打开可用项目后重新构建。"));}]];[self presentViewController:confirm animated:YES completion:nil];}]];[a addAction:[UIAlertAction actionWithTitle:DXLoc(@"查看检查点 / 结果") style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){UIViewController *page=[UIViewController new];page.title=DXLoc(@"任务记录");UITextView *v=[[UITextView alloc]initWithFrame:page.view.bounds];v.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;v.editable=NO;v.font=[UIFont monospacedSystemFontOfSize:12 weight:UIFontWeightRegular];v.text=[[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:j options:NSJSONWritingPrettyPrinted error:nil] encoding:NSUTF8StringEncoding];[page.view addSubview:v];[self.navigationController pushViewController:page animated:YES];}]];[a addAction:[UIAlertAction actionWithTitle:DXLoc(@"关闭") style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:a animated:YES completion:nil];}
@end
UIViewController *TFAIBuildQueueController(void){return [[TFAIBuildTasks alloc]initWithStyle:UITableViewStyleInsetGrouped];}
